import { Group, Mesh, PlaneGeometry, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // --- Helpers ---
  const toVec3 = (arr) => new THREE.Vector3(...arr);
  const toEuler = (arr) => new THREE.Euler(...arr);

  // --- Geometry based on atlas region aspect ratio ---
  const atlasRegion = config.atlas?.sourceRect ?? [0, 0, 512, 320];
  const regionWidth = atlasRegion[2];
  const regionHeight = atlasRegion[3];
  const aspect = regionWidth / regionHeight;

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // --- Load accent texture ---
  const accentTexture = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // --- UV transform to sample only the atlas region (fallback to full texture) ---
  // Assuming the whole texture is the atlas; if atlas dimensions are unknown we use full UV.
  const uvTransformNode = (function () {
    const uvNode = uv();
    // No explicit atlas size, so we skip scaling/offset.
    return uvNode;
  })();

  const material = new MeshBasicNodeMaterial({
    map: texture(accentTexture, uvTransformNode),
    transparent: true,
  });

  // --- Base plane mesh ---
  const plane = new Mesh(geometry, material);
  plane.position.fromArray(config.position ?? [0, 0, 0]);
  plane.rotation.fromArray(config.rotation ?? [0, 0, 0]);
  plane.scale.fromArray(config.scale ?? [1, 1, 1]);

  // --- Text overlay using font atlas ---
  const textGroup = new Group();
  if (config.textContent) {
    // Assume ctx.fontAtlas.createTextMesh returns a Mesh or Object3D ready to be added.
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: config.textContent,
      // Use the design token palette for contrast: ink on paper background.
      color: '#16161d',
      // Approximate size based on type scale; scale to fit plane height (1 unit).
      size: 0.2,
      // Anchor to center of plane.
      halign: 'center',
      valign: 'middle',
    });
    // Position the text slightly in front of the plane to avoid z‑fighting.
    textMesh.position.set(0, 0, 0.001);
    textGroup.add(textMesh);
  }

  // --- Group all elements ---
  const node = new Group();
  node.add(plane);
  node.add(textGroup);

  // --- Apply cinematic primitives if any (none in this spec) ---
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(node, primitive.params);
      }
    }
  }

  // --- UserData for external handling ---
  node.userData.handlers = {};

  // Cleanup routine
  node.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose texture if owned (assuming textureLoader returns a cached texture)
    if (accentTexture && accentTexture.isTexture && !accentTexture.__prismCached) {
      accentTexture.dispose();
    }

    // Dispose any GSAP timelines attached (none created here but safe guard)
    gsap.globalTimeline.clear();

    // Dispose text mesh if created
    if (textGroup) {
      textGroup.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose && m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
  };

  return node;
}
